package com.transiva.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class SmartReorderActivity extends Activity{static final String URL="https://transiva.my.id/server/customer_smart_reorder.php";LinearLayout root;ProgressBar p;
 protected void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.parseColor("#0B7CFF"));setContentView(ui());load();} View ui(){ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.parseColor("#F6F9FE"));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(30));s.addView(root);TextView h=t("‹  Smart Reorder",24,"#0B3A78",true);h.setOnClickListener(v->finish());root.addView(h);root.addView(t("Pesanan yang paling relevan berdasarkan frekuensi dan pesanan terbaru Anda.",13,"#64748B",false));p=new ProgressBar(this);root.addView(p);return s;}
 void load(){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(URL).openConnection();CustomerApiClient.applySecurity(this,c);StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}JSONObject o=new JSONObject(b.toString());runOnUiThread(()->render(o));}catch(Exception e){runOnUiThread(()->{p.setVisibility(View.GONE);root.addView(t("Belum dapat memuat rekomendasi.",14,"#B91C1C",true));});}},"smart-reorder").start();}
 void render(JSONObject o){p.setVisibility(View.GONE);JSONArray a=o.optJSONArray("orders");if(!o.optBoolean("success")||a==null||a.length()==0){root.addView(t("Belum ada pesanan selesai yang cukup untuk rekomendasi Smart Reorder.",14,"#64748B",false));return;}for(int i=0;i<a.length();i++){JSONObject q=a.optJSONObject(i);if(q==null)continue;LinearLayout c=box();c.addView(t(q.optString("restaurant_name","Pesanan favorit"),17,"#0B3A78",true));c.addView(t(q.optString("summary","Pesanan sebelumnya"),13,"#64748B",false));c.addView(t("Skor rekomendasi "+q.optInt("smart_score",0),12,"#0B7CFF",true));Button b=new Button(this);b.setText("Pesan Lagi");b.setAllCaps(false);b.setOnClickListener(v->{Intent in=new Intent(this,RepeatFoodOrderActivity.class);in.putExtra("repeat_order_json",q.toString());startActivity(in);});c.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));root.addView(c,lp());}}
 LinearLayout box(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(16),dp(16),dp(16),dp(16));x.setBackground(round("#FFFFFF",20));x.setElevation(dp(2));return x;}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(14),0,0);return p;}TextView t(String s,int z,String c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.parseColor(c));if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}GradientDrawable round(String c,int r){GradientDrawable g=new GradientDrawable();g.setColor(Color.parseColor(c));g.setCornerRadius(dp(r));return g;}int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}}
